DB.gen('rulers', ({ grades }) => {
  const list = [...new Map(grades.flatMap(g => RULERS[g]).map(r => [r[0], r])).values()];
  const names = list.map(r => r[0]);
  // «Кто правил раньше?» — работает и для коротких правлений
  if (list.length < 4 || R.chance(0.4)) {
    const [x, y] = R.sample(list, 2);
    const first = x[1] < y[1] ? x : y;
    const pair = R.sample(list.filter(r => r !== x && r !== y), 2).map(r => r[0]);
    return { q: `Кто из правителей правил раньше: ${x[0]} или ${y[0]}?`, a: first[0], w: [first === x ? y[0] : x[0], ...pair] };
  }
  const long = list.filter(r => r[2] - r[1] >= 2);
  const [name, from, to] = R.pick(long);
  const year = R.int(from + 1, to - 1);
  const busy = list.filter(r => r[1] <= year && year <= r[2]).map(r => r[0]);
  return { q: `Кто правил в ${year} году?`, a: name, w: R.others(names.filter(n => !busy.includes(n)), name) };
});

const rulers = (...grades) => ({ t: 'Правители и годы правления', gen: [['rulers', { grades }]], q: [] });

